from covertype import config, model
import covertype.features as F
from sklearn.ensemble import HistGradientBoostingClassifier

cfg = config.load()
d = pd.read_csv('data/covtype_cells.csv')
CUT = 2700
dist = d[d.elevation <= CUT].copy(); tr = d[d.elevation > CUT].copy()
dist['wilderness_area'] = 'cache_la_poudre'

CONT = ["elevation","aspect","slope","horizontal_distance_to_hydrology",
        "vertical_distance_to_hydrology","horizontal_distance_to_roadways",
        "hillshade_9am","hillshade_noon","hillshade_3pm","horizontal_distance_to_fire_points"]
SOIL = list(range(1,41))

def build(df, mode, soil=True):
    out = pd.DataFrame(index=df.index)
    if mode == 'raw':
        for c in CONT: out[c] = df[c].astype(float)
    elif mode == 'z':   # per-area z score, within frame
        g = df.groupby('wilderness_area')
        for c in CONT:
            m = g[c].transform('mean'); s = g[c].transform('std').replace(0,1)
            out[c] = (df[c]-m)/s
    elif mode == 'rank':
        g = df.groupby('wilderness_area')
        for c in CONT:
            out[c] = g[c].rank(pct=True)
    elif mode == 'zsoil':
        g = df.groupby('wilderness_area')
        for c in CONT:
            m = g[c].transform('mean'); s = g[c].transform('std').replace(0,1)
            out[c] = (df[c]-m)/s
    if soil:
        for s in SOIL: out[f'soil_{s}'] = (df['soil_type']==s).astype('int8')
    return out

def fitpred(mode, soil, alpha):
    X = build(tr, mode, soil); y = tr.cover_type
    if alpha>0:
        cl = np.unique(y); base={c: len(y)/(len(cl)*(y==c).sum()) for c in cl}
        w = y.map({c: base[c]**alpha for c in cl}).to_numpy()
    else: w=None
    clf = HistGradientBoostingClassifier(max_iter=150, learning_rate=0.1, random_state=0, early_stopping=False)
    clf.fit(X,y,sample_weight=w)
    p = clf.predict(build(dist, mode, soil))
    yy = dist.cover_type.values
    rec = {int(c): round(float((p[yy==c]==c).mean()),3) for c in sorted(set(yy))}
    print(mode, 'soil',soil,'alpha',alpha, rec, 'pred', pd.Series(p).value_counts(normalize=True).round(2).to_dict(), flush=True)

for mode in ['raw','z','rank']:
    for alpha in [0.0,1.0]:
