{"path": "/workspace/target/exp3.py", "content": """"Cross-fit proxy for the district: low-elevation cells held out fold-wise."""
import pandas as pd, numpy as np, copy
from sklearn.ensemble import HistGradientBoostingClassifier

d = pd.read_csv('data/covtype_cells.csv')
CONT = ["elevation","aspect","slope","horizontal_distance_to_hydrology",
        "vertical_distance_to_hydrology","horizontal_distance_to_roadways",
        "hillshade_9am","hillshade_noon","hillshade_3pm","horizontal_distance_to_fire_points"]
SOIL = list(range(1,41))
AREAS = ["rawah","neota","comanche_peak","cache_la_poudre"]

proxy_idx = d.index[d.elevation <= 2660]
print('proxy n', len(proxy_idx), d.loc[proxy_idx].cover_type.value_counts().to_dict())

def build(df, terrain=True, soil=True, area=False, drop=()):
    out = pd.DataFrame(index=df.index)
    if terrain:
        for c in CONT:
            if c not in drop: out[c] = df[c]
    if soil:
        for s in SOIL: out[f'soil_{s}'] = (df.soil_type == s).astype('int8')
    if area:
        for a in AREAS: out[f'area_{a}'] = (df.wilderness_area == a).astype('int8')
    return out

def weights(y, alpha):
    if alpha == 0: return None
    cl = np.unique(y); base = {c: len(y)/(len(cl)*(y==c).sum()) for c in cl}
    return y.map({c: base[c]**alpha for c in cl}).to_numpy()

rng = np.random.RandomState(0)
folds = rng.randint(0, 4, len(proxy_idx))

def cfgrun(tag, alpha, **kw):
    recs = {}
    preds = pd.Series(index=proxy_idx, dtype=float)
    for f in range(4):
        te = proxy_idx[folds == f]
        tr = d.drop(index=te)
        X = build(tr, **kw); y = tr.cover_type
        clf = HistGradientBoostingClassifier(max_iter=150, learning_rate=0.1,
                                             random_state=0, early_stopping=False)
        clf.fit(X, y, sample_weight=weights(y, alpha))
        preds.loc[te] = clf.predict(build(d.loc[te], **kw))
    y = d.loc[proxy_idx, 'cover_type'].values
    p = preds.values
    rec = {int(c): round(float((p[y==c]==c).mean()),3) for c in sorted(set(y))}
    bal = np.mean([rec.get(c,0.0) for c in (2,3,6)] + [0.0])
    print(f'{tag:34s} alpha={alpha}  {rec}  bal(2,3,4,6)={bal:.3f}', flush=True)

for alpha in [0.0, 0.3, 0.6, 1.0, 1.5]:
    cfgrun('terrain+soil', alpha, terrain=True, soil=True, area=False)
cfgrun('terrain+soil+area', 0.0, terrain=True, soil=True, area=True)
cfgrun('terrain+soil+area', 1.0, terrain=True, soil=True, area=True)
cfgrun('soil only', 1.0, terrain=False, soil=True, area=False)
cfgrun('terrain-noelev+soil', 1.0, terrain=True, soil=True, area=False, drop=('elevation',))
"}

